mapper.select:
SELECT post_id FROM post_bookmark
WHERE user_id = #{userId}
  AND post_id IN

      #{id}

SELECT p.post_id, p.user_id, p.minihompy_id, p.title, p.content,
       p.visibility, p.view_count, p.like_count, p.comment_count,
       p.created_at, p.updated_at
FROM post p
INNER JOIN post_bookmark pb ON p.post_id = pb.post_id
WHERE pb.user_id = #{userId}
  AND p.deleted_at IS NULL
  AND (
      p.user_id = #{userId}
      OR p.visibility = 'ALL'
      OR (
          p.visibility = 'FRIEND'
          AND EXISTS (
              SELECT 1 FROM friend f
              WHERE f.status = 'ACCEPTED'
                AND (
                    (f.requester_id = p.user_id AND f.receiver_id = #{userId})
                    OR (f.requester_id = #{userId} AND f.receiver_id = p.user_id)
                )
          )
      )
  )

    AND p.post_id < #{cursor}

ORDER BY p.post_id DESC
LIMIT #{size}
